package com.railyatra.railway.controller;
import java.time.LocalDate; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import com.railyatra.railway.realtime.AvailabilityEventPublisher;
@RestController @RequestMapping("/api/availability") public class AvailabilityStreamController {private final AvailabilityEventPublisher publisher;public AvailabilityStreamController(AvailabilityEventPublisher publisher){this.publisher=publisher;}@GetMapping(value="/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter stream(@RequestParam String trainNumber,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date,@RequestParam(name="class") String classCode,@RequestParam(defaultValue="GENERAL") String quota){return publisher.subscribe(trainNumber,date,classCode,quota);}}
